local SnuffMiller = {}
local PRODUCTS = {
    plain_ground_snuff = { name = "Navadno mleti snuf", woodCost = 1, glassCost = 1, time = 3, cost = 35, happiness = 2, prestige = 1, description = "Navadno mleti snuf za trgovce." },
    scented_snuff_jar = { name = "Dišavni snuf v kozarcu", woodCost = 1, glassCost = 1, spiceCost = 1, time = 6, cost = 100, happiness = 3, prestige = 2, description = "Dišavni snuf v steklenem kozarcu za trgovce." },
    silver_lidded_snuff = { name = "Srebrnopokrovka snuf", woodCost = 1, glassCost = 1, silverCost = 1, spiceCost = 1, time = 9, cost = 280, happiness = 4, prestige = 6, description = "Srebrnopokrovka snuf za plemiče." },
    gold_trimmed_snuff = { name = "Zlatookrasni snuf", woodCost = 1, glassCost = 1, goldCost = 1, silverCost = 1, spiceCost = 1, time = 13, cost = 680, happiness = 5, prestige = 14, description = "Zlatookrasni snuf za visoke plemiče." },
    jewel_top_snuff_box = { name = "Draguljasta snufna škatlica", woodCost = 1, glassCost = 2, goldCost = 1, silverCost = 1, jewelCost = 1, spiceCost = 1, time = 17, cost = 1500, happiness = 7, prestige = 26, description = "Snufna škatlica z draguljem za visoko plemstvo." },
    royal_grand_snuff_casket = { name = "Kraljevski veliki snufna skrinja", woodCost = 2, glassCost = 3, goldCost = 2, silverCost = 2, jewelCost = 2, pearlCost = 2, spiceCost = 2, time = 24, cost = 3500, happiness = 12, prestige = 56, description = "Velika kraljevska snufna skrinja z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    snuff_cottage = { name = "Snufna koča", cost = { gold = 220, wood = 120, stone = 100, glass = 4 }, upkeep = 5, qualityBonus = 5 },
    milling_loft = { name = "Mlinska podstrešje", cost = { gold = 800, wood = 240, stone = 240, silver = 6, glass = 6 }, upkeep = 18, qualityBonus = 18 },
    master_snuff_atelier = { name = "Mojstrski snufni atelje", cost = { gold = 2300, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 52, qualityBonus = 30 },
    royal_snuff_palace = { name = "Kraljevska snufna palača", cost = { gold = 9500, wood = 580, stone = 740, gold = 60, jewel = 16 }, upkeep = 190, qualityBonus = 55, prestigeBonus = 50 },
}
SnuffMiller.woodStock = 14; SnuffMiller.glassStock = 12; SnuffMiller.spiceStock = 8; SnuffMiller.silverStock = 6; SnuffMiller.goldStock = 6; SnuffMiller.jewelStock = 4; SnuffMiller.pearlStock = 4
SnuffMiller.productStock = {}; SnuffMiller.buildings = {}; SnuffMiller.maker = nil; SnuffMiller.activeMaking = {}; SnuffMiller.totalProducts = 0; SnuffMiller.dayTimer = 0
function SnuffMiller.init() SnuffMiller.woodStock=14; SnuffMiller.glassStock=12; SnuffMiller.spiceStock=8; SnuffMiller.silverStock=6; SnuffMiller.goldStock=6; SnuffMiller.jewelStock=4; SnuffMiller.pearlStock=4; SnuffMiller.productStock={}; SnuffMiller.buildings={}; SnuffMiller.maker=nil; SnuffMiller.activeMaking={}; SnuffMiller.totalProducts=0; SnuffMiller.dayTimer=0; print("[SnuffMiller] Royal Snuff Miller System initialized (6 products, 4 buildings)") end
function SnuffMiller.hireMaker(n,s) s=s or math.random(55,90); local c=460+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SnuffMiller.maker={name=n or ("Snuftar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Snuftar najet: %s (spretnost: %d)",SnuffMiller.maker.name,s),"success") end; return true end
function SnuffMiller.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SnuffMiller.build(id) local ok,e=SnuffMiller.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SnuffMiller.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SnuffMiller.getQualityBonus() local b=0; for _,bd in ipairs(SnuffMiller.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SnuffMiller.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and SnuffMiller.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.glassCost and SnuffMiller.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.spiceCost and SnuffMiller.spiceStock<(d.spiceCost or 0) then return false,"Premalo začimb" end; if d.silverCost and SnuffMiller.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SnuffMiller.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SnuffMiller.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and SnuffMiller.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #SnuffMiller.buildings==0 then return false,"Potrebna snufna koča" end; if not SnuffMiller.maker then return false,"Potreben snuftar" end; return true end
function SnuffMiller.make(pt,qty) qty=qty or 1; local ok,e=SnuffMiller.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then SnuffMiller.woodStock=SnuffMiller.woodStock-d.woodCost*qty end; if d.glassCost then SnuffMiller.glassStock=SnuffMiller.glassStock-d.glassCost*qty end; if d.spiceCost then SnuffMiller.spiceStock=SnuffMiller.spiceStock-d.spiceCost*qty end; if d.silverCost then SnuffMiller.silverStock=SnuffMiller.silverStock-d.silverCost*qty end; if d.goldCost then SnuffMiller.goldStock=SnuffMiller.goldStock-d.goldCost*qty end; if d.jewelCost then SnuffMiller.jewelStock=SnuffMiller.jewelStock-d.jewelCost*qty end; if d.pearlCost then SnuffMiller.pearlStock=SnuffMiller.pearlStock-d.pearlCost*qty end; local t=d.time; if SnuffMiller.maker then t=math.max(1,t-math.floor(SnuffMiller.maker.skill/13)) end; table.insert(SnuffMiller.activeMaking,{id="snuff_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Mletje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SnuffMiller.completeMaking(m) local q=1.0+(SnuffMiller.getQualityBonus()/100); if SnuffMiller.maker then q=q+(SnuffMiller.maker.skill/150) end; q=math.min(2.4,q); SnuffMiller.productStock[m.productType]=(SnuffMiller.productStock[m.productType] or 0)+m.quantity; SnuffMiller.totalProducts=SnuffMiller.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SnuffMiller.maker then SnuffMiller.maker.itemsMade=SnuffMiller.maker.itemsMade+m.quantity; if math.random()<0.25 then SnuffMiller.maker.skill=math.min(100,SnuffMiller.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Snuf pripravljen: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"snuff.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function SnuffMiller.update(dt) if not _G.state then return end; SnuffMiller.dayTimer=SnuffMiller.dayTimer+dt; if SnuffMiller.dayTimer>=30 then SnuffMiller.dayTimer=0; for i=#SnuffMiller.activeMaking,1,-1 do local m=SnuffMiller.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SnuffMiller.completeMaking(m); table.remove(SnuffMiller.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SnuffMiller.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SnuffMiller.maker then tu=tu+12 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SnuffMiller.getStats() return {woodStock=SnuffMiller.woodStock,glassStock=SnuffMiller.glassStock,spiceStock=SnuffMiller.spiceStock,silverStock=SnuffMiller.silverStock,goldStock=SnuffMiller.goldStock,jewelStock=SnuffMiller.jewelStock,pearlStock=SnuffMiller.pearlStock,productStock=SnuffMiller.productStock,numBuildings=#SnuffMiller.buildings,hasMaker=SnuffMiller.maker~=nil,makerName=SnuffMiller.maker and SnuffMiller.maker.name or "—",makerSkill=SnuffMiller.maker and SnuffMiller.maker.skill or 0,activeMaking=#SnuffMiller.activeMaking,totalProducts=SnuffMiller.totalProducts} end
return SnuffMiller
